import crypto from 'crypto';
import { Redis } from 'ioredis';

interface DeploymentPayload {
  tenantId: string;
  pipelineId: string;
  commitSha: string;
  timestamp: number;
  artifacts: string[];
}

interface SignedRequest {
  payload: DeploymentPayload;
  signature: string;
  nonce: string;
  keyId: string;
}

class TenantKeyStore {
  private keys: Map<string, Map<string, Buffer>> = new Map();

  registerKey(tenantId: string, keyId: string, publicKey: Buffer): void {
    if (!this.keys.has(tenantId)) {
      this.keys.set(tenantId, new Map());
    }
    this.keys.get(tenantId)!.set(keyId, publicKey);
  }

  getKey(tenantId: string, keyId: string): Buffer | undefined {
    return this.keys.get(tenantId)?.get(keyId);
  }
}

class NonceRegistry {
  private redis: Redis;
  private readonly TTL_SECONDS = 300;

  constructor(redisUrl: string) {
    this.redis = new Redis(redisUrl);
  }

  async checkAndStore(nonce: string, tenantId: string): Promise<boolean> {
    const key = `nonce:${tenantId}:${nonce}`;
    const result = await this.redis.set(key, '1', 'EX', this.TTL_SECONDS, 'NX');
    return result === 'OK';
  }
}

class DeploymentGateway {
  private keyStore: TenantKeyStore;
  private nonceRegistry: NonceRegistry;
  private readonly MAX_CLOCK_SKEW_MS = 30000;

  constructor(keyStore: TenantKeyStore, nonceRegistry: NonceRegistry) {
    this.keyStore = keyStore;
    this.nonceRegistry = nonceRegistry;
  }

  private computeSignaturePayload(payload: DeploymentPayload, nonce: string): Buffer {
    const canonical = JSON.stringify({
      tenantId: payload.tenantId,
      pipelineId: payload.pipelineId,
      commitSha: payload.commitSha,
      timestamp: payload.timestamp,
      artifacts: payload.artifacts.sort()
    });
    return Buffer.from(canonical + nonce, 'utf-8');
  }

  private verifySignature(publicKey: Buffer, signature: string, data: Buffer): boolean {
    const verify = crypto.createVerify('SHA256');
    verify.update(data);
    try {
      return verify.verify(publicKey, Buffer.from(signature, 'base64'));
    } catch {
      return false;
    }
  }

  async processDeployment(request: SignedRequest): Promise<{ success: boolean; error?: string }> {
    const { payload, signature, nonce, keyId } = request;

    // Step 1: Validate timestamp freshness
    const now = Date.now();
    if (Math.abs(now - payload.timestamp) > this.MAX_CLOCK_SKEW_MS) {
      return { success: false, error: 'Request timestamp outside acceptable window' };
    }

    // Step 2: Authorize - ensure the signing key belongs to the payload tenant
    const keyTenantId = this.extractTenantFromKeyId(keyId);
    if (keyTenantId !== payload.tenantId) {
      return { success: false, error: 'Tenant mismatch: key does not belong to payload tenant' };
    }

    // Step 3: Resolve signing key using payload's tenantId for lookup
    const publicKey = this.keyStore.getKey(payload.tenantId, keyId);
    if (!publicKey) {
      return { success: false, error: 'Unknown signing key' };
    }

    // Step 4: Check nonce uniqueness BEFORE signature verification (fail fast)
    const nonceValid = await this.nonceRegistry.checkAndStore(nonce, payload.tenantId);
    if (!nonceValid) {
      return { success: false, error: 'Nonce already used' };
    }

    // Step 5: Verify cryptographic signature
    const signatureData = this.computeSignaturePayload(payload, nonce);
    if (!this.verifySignature(publicKey, signature, signatureData)) {
      return { success: false, error: 'Invalid signature' };
    }

    // Step 6: Execute deployment
    await this.executeDeployment(payload);
    return { success: true };
  }

  private extractTenantFromKeyId(keyId: string): string {
    // keyId format: "tenant:<tenantId>:key:<keyHash>"
    const parts = keyId.split(':');
    return parts[1] || '';
  }

  private async executeDeployment(payload: DeploymentPayload): Promise<void> {
    console.log(`Deploying ${payload.commitSha} for tenant ${payload.tenantId}`);
    // ... actual deployment logic
  }
}

export { DeploymentGateway, TenantKeyStore, NonceRegistry, SignedRequest, DeploymentPayload };
